package com.legionlexi.nyloprogressbar;

import org.junit.Test;
import static org.junit.Assert.*;

public class WaveProgressTest
{
	@Test
	public void simultaneousSpawnsCountAsOneWaveAndSplitsDoNotCount()
	{
		WaveProgress progress = new WaveProgress();
		progress.reset(true);
		progress.observeSpawn(100, true);
		progress.observeSpawn(100, true);
		progress.observeSpawn(101, false);
		assertEquals(1, progress.wave());
		assertEquals(3, progress.percent());
		progress.observeSpawn(150, true); // A stall does not add extra waves.
		assertEquals(2, progress.wave());
	}

	@Test
	public void lastWaveCannotFinishUntilBossAppears()
	{
		WaveProgress progress = new WaveProgress();
		progress.reset(true);
		for (int wave = 1; wave <= 31; wave++)
		{
			progress.observeSpawn(wave * 4, true);
			assertTrue(progress.percent() < 100);
		}
		assertEquals(99, progress.percent());
		progress.bossAppeared();
		assertEquals(100, progress.percent());
		progress.observeSpawn(500, true);
		assertEquals(31, progress.wave());
	}

	@Test
	public void unknownStartDoesNotFabricatePercentage()
	{
		WaveProgress progress = new WaveProgress();
		progress.reset(false);
		progress.observeSpawn(12, true);
		assertFalse(progress.known());
		assertEquals(0, progress.wave());
		progress.bossAppeared();
		assertTrue(progress.known());
		assertEquals(100, progress.percent());
	}

	@Test
	public void percentageOnlyMovesForwardWithObservedWaves()
	{
		WaveProgress progress = new WaveProgress();
		progress.reset(true);
		int previous = 0;
		for (int wave = 1; wave <= 31; wave++)
		{
			progress.observeSpawn(wave * 4, true);
			assertTrue(progress.percent() >= previous);
			previous = progress.percent();
		}
		assertEquals(99, previous);
	}

	@Test
	public void resetStartsANewAttempt()
	{
		WaveProgress progress = new WaveProgress();
		progress.reset(true);
		progress.observeSpawn(4, true);
		progress.bossAppeared();
		progress.reset(true);
		assertEquals(0, progress.percent());
		assertFalse(progress.complete());
		progress.observeSpawn(4, true);
		assertEquals(1, progress.wave());
	}

	@Test
	public void allEntranceTilesAndInteriorSplits()
	{
		int[][] entrances = {{17,24},{17,25},{18,25},{31,9},{32,9},{32,10},{46,24},{46,25},{47,25}};
		for (int[] tile : entrances) { assertTrue(WaveProgress.isEntrance(tile[0], tile[1])); }
		assertFalse(WaveProgress.isEntrance(32, 24));
		assertFalse(WaveProgress.isEntrance(25, 25));
	}

	@Test
	public void supportsAllModesButNotHardModeMinibossOrVerzikNylos()
	{
		assertTrue(NyloProgressBarPlugin.isWaveNpc(8342));
		assertTrue(NyloProgressBarPlugin.isWaveNpc(10785));
		assertTrue(NyloProgressBarPlugin.isWaveNpc(10802));
		assertFalse(NyloProgressBarPlugin.isWaveNpc(8381));
		assertFalse(NyloProgressBarPlugin.isBoss(10803));
		assertTrue(NyloProgressBarPlugin.isBoss(8354));
		assertTrue(NyloProgressBarPlugin.isBoss(10786));
		assertTrue(NyloProgressBarPlugin.isBoss(10807));
	}
}

