package com.legionlexi.nyloprogressbar;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayPosition;

public class NyloProgressBarOverlay extends Overlay
{
	private static final int WIDTH = 220;
	private final NyloProgressBarPlugin plugin;

	@Inject
	NyloProgressBarOverlay(NyloProgressBarPlugin plugin)
	{
		this.plugin = plugin;
		setPosition(OverlayPosition.ABOVE_CHATBOX_RIGHT);
		setMovable(true);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!plugin.visible()) { return null; }
		WaveProgress progress = plugin.progress();
		String title = progress.complete() ? "Waves complete - boss is here"
			: progress.wave() == 31 ? "Nylo - clearing final wave"
			: "Nylo wave progress";
		paintBar(graphics, title, progress.percent());
		return new Dimension(WIDTH, 48);
	}

	static void paintBar(Graphics2D graphics, String title, int percent)
	{
		graphics.setColor(new Color(20, 23, 20, 220));
		graphics.fillRoundRect(0, 0, WIDTH, 48, 8, 8);
		graphics.setColor(new Color(226, 231, 226));
		graphics.drawString(title, 8, 16);
		graphics.setColor(new Color(43, 49, 43));
		graphics.fillRect(8, 23, WIDTH - 16, 18);
		graphics.setColor(new Color(51, 190, 77));
		graphics.fillRect(8, 23, (WIDTH - 16) * Math.max(0, percent) / 100, 18);
		String text = percent + "%";
		FontMetrics metrics = graphics.getFontMetrics();
		int x = (WIDTH - metrics.stringWidth(text)) / 2;
		graphics.setColor(Color.BLACK);
		graphics.drawString(text, x + 1, 37);
		graphics.setColor(Color.WHITE);
		graphics.drawString(text, x, 36);
	}
}

package com.legionlexi.nyloprogressbar;

/** Tracks observed spawn batches, never elapsed time or predicted waves. */
final class WaveProgress
{
	static final int TOTAL_WAVES = 31;
	private int wave;
	private int lastSpawnTick = Integer.MIN_VALUE;
	private boolean known;
	private boolean complete;

	void reset(boolean known)
	{
		wave = 0;
		lastSpawnTick = Integer.MIN_VALUE;
		this.known = known;
		complete = false;
	}

	void observeSpawn(int tick, boolean entrance)
	{
		if (!known || complete || !entrance || tick == lastSpawnTick)
		{
			return;
		}
		lastSpawnTick = tick;
		wave = Math.min(TOTAL_WAVES, wave + 1);
	}

	void bossAppeared()
	{
		complete = true;
		known = true;
	}

	int percent()
	{
		if (complete)
		{
			return 100;
		}
		return Math.min(99, wave * 100 / TOTAL_WAVES);
	}

	int wave() { return wave; }
	boolean known() { return known; }
	boolean complete() { return complete; }

	static boolean isEntrance(int x, int y)
	{
		return (x == 17 && (y == 24 || y == 25))
			|| (x == 18 && y == 25)
			|| ((x == 31 || x == 32) && y == 9)
			|| (x == 32 && y == 10)
			|| (x == 46 && (y == 24 || y == 25))
			|| (x == 47 && y == 25);
	}
}

package com.legionlexi.nyloprogressbar;

import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.NPC;
import net.runelite.api.ChatMessageType;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.NpcSpawned;
import net.runelite.api.gameval.NpcID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@PluginDescriptor(
	name = "Nylo Progress Bar",
	description = "A green, movable progress bar for the Nylocas waves in Theatre of Blood",
	tags = {"tob", "nylo", "nylocas", "waves", "progress"}
)
public class NyloProgressBarPlugin extends Plugin
{
	private static final int NYLOCAS_REGION = 13122;
	@Inject private Client client;
	@Inject private ClientThread clientThread;
	@Inject private OverlayManager overlayManager;
	@Inject private NyloProgressBarOverlay overlay;
	private final WaveProgress progress = new WaveProgress();
	private boolean inRoom;
	private boolean enabled;
	private int completedTick;

	@Override
	protected void startUp()
	{
		enabled = true;
		overlayManager.add(overlay);
		clientThread.invoke(() ->
		{
			if (!enabled) { return; }
			inRoom = isInRoom();
			progress.reset(inRoom);
			if (inRoom) { inspectExistingNpcs(); }
		});
	}

	@Override
	protected void shutDown()
	{
		enabled = false;
		overlayManager.remove(overlay);
		inRoom = false;
		progress.reset(false);
	}

	private boolean isInRoom()
	{
		return client.getLocalPlayer() != null
			&& WorldPoint.fromLocalInstance(client, client.getLocalPlayer().getLocalLocation())
				.getRegionID() == NYLOCAS_REGION;
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		boolean nowInRoom = isInRoom();
		if (nowInRoom != inRoom)
		{
			inRoom = nowInRoom;
			progress.reset(nowInRoom);
			if (nowInRoom)
			{
				inspectExistingNpcs();
			}
		}
	}

	private void inspectExistingNpcs()
	{
		// Scan only on entry/startup, never every frame or tick.
		boolean bossPresent = false;
		for (NPC npc : client.getNpcs())
		{
			bossPresent |= isBoss(npc.getId());
		}
		if (bossPresent) { finish(); }
	}

	@Subscribe
	public void onNpcSpawned(NpcSpawned event)
	{
		if (!inRoom || client.getGameState() != GameState.LOGGED_IN) { return; }
		NPC npc = event.getNpc();
		if (isBoss(npc.getId())) { finish(); return; }
		if (!isWaveNpc(npc.getId())) { return; }
		WorldPoint point = WorldPoint.fromLocalInstance(client, npc.getLocalLocation());
		progress.observeSpawn(client.getTickCount(),
			point.getRegionID() == NYLOCAS_REGION
				&& WaveProgress.isEntrance(point.getRegionX(), point.getRegionY()));
	}

	private void finish()
	{
		if (!progress.complete())
		{
			progress.bossAppeared();
			completedTick = client.getTickCount();
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGIN_SCREEN
			|| event.getGameState() == GameState.HOPPING
			|| event.getGameState() == GameState.CONNECTION_LOST)
		{
			progress.reset(false);
			inRoom = false;
		}
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (inRoom && event.getType() == ChatMessageType.GAMEMESSAGE
			&& event.getMessage().equals("You have failed. The vampyres take pity on you and allow you to try again..."))
		{
			progress.reset(true);
		}
	}

	boolean visible()
	{
		return inRoom && client.getGameState() == GameState.LOGGED_IN
			&& (!progress.complete() || client.getTickCount() - completedTick < 10);
	}

	WaveProgress progress() { return progress; }

	static boolean isWaveNpc(int id)
	{
		return (id >= NpcID.TOB_NYLOCAS_INCOMING_MELEE && id <= NpcID.TOB_NYLOCAS_BIG_FIGHTING_MAGIC)
			|| (id >= NpcID.TOB_NYLOCAS_INCOMING_MELEE_STORY && id <= NpcID.TOB_NYLOCAS_BIG_FIGHTING_MAGIC_STORY)
			|| (id >= NpcID.TOB_NYLOCAS_INCOMING_MELEE_HARD && id <= NpcID.TOB_NYLOCAS_BIG_FIGHTING_MAGIC_HARD);
	}

	static boolean isBoss(int id)
	{
		return (id >= NpcID.NYLOCAS_BOSS_SPAWNING && id <= NpcID.NYLOCAS_BOSS_RANGED)
			|| (id >= NpcID.NYLOCAS_BOSS_SPAWNING_STORY && id <= NpcID.NYLOCAS_BOSS_RANGED_STORY)
			|| (id >= NpcID.NYLOCAS_BOSS_SPAWNING_HARD && id <= NpcID.NYLOCAS_BOSS_RANGED_HARD);
	}
}
